"""Authoring source. Outputs independent, editable UTF-8 JSON content packs."""
import json
from pathlib import Path
P = {}

def add(cat, source, tags=()):
    out = P.setdefault(cat, [])
    for line in source.strip().split('|'):
        text = line.strip()
        if text:
            out.append({'id':f'{cat}_{len(out)+1:03}', 'text':text,'tags':list(tags)})

